# Discount rules applied to cart lines.


def percent_off(line_cents, percent):
    # discount in cents for a single cart line
    return int(line_cents * percent / 100)


def apply_discounts(lines, percent):
    # returns (total after discount, discount) in cents
    discount = sum(percent_off(cents, percent) for cents in lines)
    return sum(lines) - discount, discount

