from .money import to_cents
from .discounts import apply_discounts


class Cart:
    def __init__(self, discount_percent=0):
        self.discount_percent = discount_percent
        self.items = []

    def add(self, name, price, qty=1):
        self.items.append((name, to_cents(price), qty))

    def line_totals(self):
        return [cents * qty for _, cents, qty in self.items]

    def total(self):
        total, _ = apply_discounts(self.line_totals(), self.discount_percent)
        return total

