from .money import format_cents
from .discounts import apply_discounts


def render(cart):
    lines = []
    for name, cents, qty in cart.items:
        lines.append(f'{name} x{qty}  {format_cents(cents * qty)}')
    _, discount = apply_discounts(cart.line_totals(), cart.discount_percent)
    if discount:
        lines.append(f'Discount ({cart.discount_percent}%)  -{format_cents(discount)}')
    lines.append(f'TOTAL  {format_cents(cart.total())}')
    return '\n'.join(lines)
